	 * Returns the alias of the secret-key entry at ARG1. Indexing begins at 0; valid indexes range from 0 through NumSecretKeys - 1.
	 * @see https://www.chilkatsoft.com/refdoc/phpCkJavaKeyStoreRef.html#GetSecretKeyAlias
	 * @param int $index
	 * @return ?string
	 */
	function secretKeyAlias($index) {
		return CkJavaKeyStore_secretKeyAlias($this->_cPtr,$index);
	}

	/**
	 * Deprecated: Use TrustedCertAt instead. Returns the trusted certificate at ARG1. Indexing begins at 0; the valid range is determined by NumTrustedCerts.
	 * @see https://www.chilkatsoft.com/refdoc/phpCkJavaKeyStoreRef.html#GetTrustedCert
	 * @param int $index
	 * @return ?CkCert
	 * @deprecated
	 */
	function GetTrustedCert($index) {
		return chilkat::_obj(CkJavaKeyStore_GetTrustedCert($this->_cPtr,$index),'CkCert');
	}

	/**
	 * Returns the alias of the trusted-certificate entry at ARG1. Indexing begins at 0; valid indexes range from 0 through NumTrustedCerts - 1.
	 * @see https://www.chilkatsoft.com/refdoc/phpCkJavaKeyStoreRef.html#GetTrustedCertAlias
	 * @param int $index
	 * @return ?string
	 */
	function getTrustedCertAlias($index) {
		return CkJavaKeyStore_getTrustedCertAlias($this->_cPtr,$index);
	}

	/**
	 * Returns the alias of the trusted-certificate entry at ARG1. Indexing begins at 0; valid indexes range from 0 through NumTrustedCerts - 1.
	 * @see https://www.chilkatsoft.com/refdoc/phpCkJavaKeyStoreRef.html#GetTrustedCertAlias
	 * @param int $index
	 * @return ?string
	 */
	function trustedCertAlias($index) {
		return CkJavaKeyStore_trustedCertAlias($this->_cPtr,$index);
	}

	/**
	 * Loads a JKS or JCEKS keystore from the bytes currently contained in ARG2. ARG1 is the store password used for integrity verification when VerifyKeyedDigest is enabled.
	 * @see https://www.chilkatsoft.com/refdoc/phpCkJavaKeyStoreRef.html#LoadBd
	 * @param ?string $password
	 * @param CkBinData $bd
	 * @return bool
	 */
	function LoadBd($password,$bd) {
		return CkJavaKeyStore_LoadBd($this->_cPtr,$password,$bd);
	}

	/**
	 * Loads a JKS or JCEKS keystore from the serialized bytes in ARG2. ARG1 is the store password used for store-level integrity verification when VerifyKeyedDigest is enabled.Two password layers: Loading the store does not require Chilkat to decrypt every private or secret key. The passwords protecting individual key entries are supplied later when those keys are retrieved or exported.
	 * @see https://www.chilkatsoft.com/refdoc/phpCkJavaKeyStoreRef.html#LoadBinary
	 * @param ?string $password
	 * @param CkByteData $jksData
	 * @return bool
	 */
	function LoadBinary($password,$jksData) {
		return CkJavaKeyStore_LoadBinary($this->_cPtr,$password,$jksData);
	}

	/**
	 * Decodes the serialized keystore text in ARG2 using the binary encoding named by ARG3, then loads the resulting JKS or JCEKS bytes. Common encodings include base64, hex, and base64url. ARG1 is the store password used for integrity verification.Encoding is not encryption: ARG3 describes how binary keystore bytes are represented as text. It does not name the keystore format and does not protect the data cryptographically.
	 * @see https://www.chilkatsoft.com/refdoc/phpCkJavaKeyStoreRef.html#LoadEncoded
	 * @param ?string $password
	 * @param ?string $jksEncData
	 * @param ?string $encoding
	 * @return bool
	 */
	function LoadEncoded($password,$jksEncData,$encoding) {
		return CkJavaKeyStore_LoadEncoded($this->_cPtr,$password,$jksEncData,$encoding);
	}

	/**
	 * Loads a JKS or JCEKS keystore from the file at ARG2. ARG1 is the store password used to verify the keystore-level integrity digest when VerifyKeyedDigest is enabled.JKS/JCEKS versus PKCS #12: This class is intended for the proprietary Java JKS and JCEKS formats. Modern Java releases use PKCS #12 as the default keystore type; use Chilkat.Pfx when the input is a .p12 or .pfx container.
	 * @see https://www.chilkatsoft.com/refdoc/phpCkJavaKeyStoreRef.html#LoadFile
	 * @param ?string $password
	 * @param ?string $path
	 * @return bool
	 */
	function LoadFile($password,$path) {
		return CkJavaKeyStore_LoadFile($this->_cPtr,$password,$path);
	}

	/**
	 * Loads supported keys from the JWK Set in ARG2 into this Java keystore object. ARG1 is used to protect imported private-key and secret-key entries. A JWK kid value is used as the entry alias when present.JWK Set structure: ARG2 should contain a JSON object with a keys array. Private asymmetric JWKs contain private parameters such as d; symmetric JWKs use kty: "oct" and contain the key in k. Treat the input as sensitive whenever it contains private or symmetric key material.
	 * @see https://www.chilkatsoft.com/refdoc/phpCkJavaKeyStoreRef.html#LoadJwkSet
	 * @param ?string $password
	 * @param CkJsonObject $jwkSet
	 * @return bool
	 */
	function LoadJwkSet($password,$jwkSet) {
		return CkJavaKeyStore_LoadJwkSet($this->_cPtr,$password,$jwkSet);
	}

	/**
	 * Loads ARG3 with the private key at zero-based index ARG2. ARG1 is the password protecting that private-key entry. Valid indexes range from 0 through NumPrivateKeys - 1.Use the entry password: ARG1 is not necessarily the password used to load the complete keystore. Java keystores can protect each private-key entry with a different password.
	 * @see https://www.chilkatsoft.com/refdoc/phpCkJavaKeyStoreRef.html#PrivateKeyAt
	 * @param ?string $password
	 * @param int $index
	 * @param CkPrivateKey $privKey
	 * @return bool
	 */
	function PrivateKeyAt($password,$index,$privKey) {
		return CkJavaKeyStore_PrivateKeyAt($this->_cPtr,$password,$index,$privKey);
	}

	/**
	 * Searches the private-key entries for an alias equal to ARG2 and loads the matching private key into ARG4. ARG1 is the password protecting that key entry, and ARG3 controls whether the alias comparison is case-sensitive.
	 * @see https://www.chilkatsoft.com/refdoc/phpCkJavaKeyStoreRef.html#PrivateKeyOf
	 * @param ?string $password
	 * @param ?string $alias
	 * @param bool $caseSensitive
	 * @param CkPrivateKey $privKey
	 * @return bool
	 */
	function PrivateKeyOf($password,$alias,$caseSensitive,$privKey) {
		return CkJavaKeyStore_PrivateKeyOf($this->_cPtr,$password,$alias,$caseSensitive,$privKey);
	}

	/**
	 * Removes an entry selected by type and zero-based index. ARG1 uses the following documented values:ARG1Entry selected 1Trusted-certificate entry; ARG2 indexes the trusted-certificate list. 2Private-key entry; ARG2 indexes the private-key list. ARG2 is an index within the selected entry category, not an index across all entries in the keystore. In-memory change: This method modifies the current object. Call ToFile, ToBd, or another To* method to persist the updated keystore.
	 * @see https://www.chilkatsoft.com/refdoc/phpCkJavaKeyStoreRef.html#RemoveEntry
	 * @param int $entryType
	 * @param int $index
	 * @return bool
	 */
	function RemoveEntry($entryType,$index) {
		return CkJavaKeyStore_RemoveEntry($this->_cPtr,$entryType,$index);
	}

	/**
	 * Changes the alias of an entry selected by type and zero-based index. ARG1 uses the following documented values:ARG1Entry selected 1Trusted-certificate entry; ARG2 indexes the trusted-certificate list. 2Private-key entry; ARG2 indexes the private-key list. ARG3 is the new alias. The index is relative to the selected category, not the complete set of keystore entries. Choose aliases carefully: Aliases identify entries within a Java keystore, but case sensitivity is implementation-dependent. Use unique aliases that do not differ only by case.
	 * @see https://www.chilkatsoft.com/refdoc/phpCkJavaKeyStoreRef.html#SetAlias
	 * @param int $entryType
	 * @param int $index
	 * @param ?string $alias
	 * @return bool
	 */
	function SetAlias($entryType,$index,$alias) {
		return CkJavaKeyStore_SetAlias($this->_cPtr,$entryType,$index,$alias);
	}

	/**
	 * Serializes the current Java keystore and writes the complete JKS or JCEKS file image to ARG2. ARG1 is the store password used to create the keystore-level integrity digest.Separate entry protection: Private-key and secret-key entries may have passwords distinct from the store password. Serializing with ARG1 does not automatically change those entry passwords.
	 * @see https://www.chilkatsoft.com/refdoc/phpCkJavaKeyStoreRef.html#ToBd
	 * @param ?string $password
	 * @param CkBinData $bd
	 * @return bool
	 */
	function ToBd($password,$bd) {
		return CkJavaKeyStore_ToBd($this->_cPtr,$password,$bd);
	}

	/**
	 * Serializes the current Java keystore and returns the complete JKS or JCEKS file image as bytes. ARG1 is the store password used to create the keystore-level integrity digest.Store password versus entry passwords: The store password protects the integrity of the serialized keystore. Private-key and secret-key entries may remain protected by their own entry passwords, which were supplied when the entries were added or changed. The store password is not general-purpose encryption for all aliases and certificates in the file.
	 * @see https://www.chilkatsoft.com/refdoc/phpCkJavaKeyStoreRef.html#ToBinary
	 * @param ?string $password
	 * @param CkByteData $outBytes
	 * @return bool
	 */
	function ToBinary($password,$outBytes) {
		return CkJavaKeyStore_ToBinary($this->_cPtr,$password,$outBytes);
	}

	/**
	 * Serializes the current Java keystore and returns the resulting JKS or JCEKS bytes encoded as text using ARG2. Common choices include base64, hex, and base64url. ARG1 is the store password used to create the keystore-level integrity digest.
	 * @see https://www.chilkatsoft.com/refdoc/phpCkJavaKeyStoreRef.html#ToEncodedString
	 * @param ?string $password
	 * @param ?string $encoding
	 * @return ?string
	 */
	function toEncodedString($password,$encoding) {
		return CkJavaKeyStore_toEncodedString($this->_cPtr,$password,$encoding);
	}

	/**
	 * Serializes the current Java keystore and writes the complete JKS or JCEKS file image to ARG2. ARG1 is the store password used to create the keystore-level integrity digest.Password roles: The store password may differ from the passwords protecting individual private-key or secret-key entries. Saving with a new store password does not automatically change each entry password; use ChangePassword for private-key entries when needed.
	 * @see https://www.chilkatsoft.com/refdoc/phpCkJavaKeyStoreRef.html#ToFile
	 * @param ?string $password
	 * @param ?string $path
	 * @return bool
	 */
	function ToFile($password,$path) {
		return CkJavaKeyStore_ToFile($this->_cPtr,$password,$path);
	}

	/**
	 * Exports supported private-key and secret-key entries as a JSON Web Key Set and writes the JSON to ARG2. ARG1 is used to recover protected key entries. Each exported JWK receives a kid value derived from the keystore alias.Sensitive output: A JWK containing private parameter d or symmetric parameter k contains secret key material. Protect the resulting JSON as carefully as the original keystore and do not log or transmit it over an untrusted channel.
	 * @see https://www.chilkatsoft.com/refdoc/phpCkJavaKeyStoreRef.html#ToJwkSet
	 * @param ?string $password
	 * @param CkStringBuilder $sbJwkSet
	 * @return bool
	 */
	function ToJwkSet($password,$sbJwkSet) {
		return CkJavaKeyStore_ToJwkSet($this->_cPtr,$password,$sbJwkSet);
	}

	/**
	 * Deprecated: Use ToPemObj instead. Converts the keystore material supported by the Pem class and returns a new Pem object. ARG1 is used to decrypt private-key entries during the conversion. Private-key password: The supplied password must recover the private-key entries included in the conversion. The returned Pem object is an in-memory representation; its later serialization settings determine how PEM output is formatted or encrypted.
	 * @see https://www.chilkatsoft.com/refdoc/phpCkJavaKeyStoreRef.html#ToPem
	 * @param ?string $password
	 * @return ?CkPem
	 * @deprecated
	 */
	function ToPem($password) {
		return chilkat::_obj(CkJavaKeyStore_ToPem($this->_cPtr,$password),'CkPem');
	}

	/**
	 * Converts the keystore material supported by the Pem class and loads the result into ARG2. ARG1 is used to decrypt private-key entries during the conversion.Output handling: The destination Pem object receives the converted material in memory. Its own export methods and properties control whether later PEM text is encrypted and how it is formatted. Treat unencrypted private-key PEM as sensitive data.
	 * @see https://www.chilkatsoft.com/refdoc/phpCkJavaKeyStoreRef.html#ToPemObj
	 * @param ?string $password
	 * @param CkPem $pemObj
	 * @return bool
	 */
	function ToPemObj($password,$pemObj) {
		return CkJavaKeyStore_ToPemObj($this->_cPtr,$password,$pemObj);
	}

	/**
	 * Deprecated: Use ToPfxObj instead. Converts the certificates and recoverable private-key entries in the Java keystore to a new Pfx object. ARG1 is used to decrypt the private-key entries being exported.
	 * @see https://www.chilkatsoft.com/refdoc/phpCkJavaKeyStoreRef.html#ToPfx
	 * @param ?string $password
	 * @return ?CkPfx
	 * @deprecated
	 */
	function ToPfx($password) {
		return chilkat::_obj(CkJavaKeyStore_ToPfx($this->_cPtr,$password),'CkPfx');
	}

	/**
	 * Converts the certificates and recoverable private-key entries in the Java keystore and loads the result into ARG2. ARG1 is used to decrypt private-key entries during the conversion.Conversion password: ARG1 is an input password for recovering the Java keystore entries. It is not automatically the password that will protect a later serialized PFX; use the destination Pfx export method to choose the PFX password.
	 * @see https://www.chilkatsoft.com/refdoc/phpCkJavaKeyStoreRef.html#ToPfxObj
	 * @param ?string $password
	 * @param CkPfx $pfxObj
	 * @return bool
	 */
	function ToPfxObj($password,$pfxObj) {
		return CkJavaKeyStore_ToPfxObj($this->_cPtr,$password,$pfxObj);
	}

	/**
	 * Loads ARG2 with the trusted certificate at the zero-based index ARG1. Valid indexes range from 0 through NumTrustedCerts - 1. The returned certificate is the single certificate stored in the trust entry and has no private key merely by virtue of being trusted.
	 * @see https://www.chilkatsoft.com/refdoc/phpCkJavaKeyStoreRef.html#TrustedCertAt
	 * @param int $index
	 * @param CkCert $cert
	 * @return bool
	 */
	function TrustedCertAt($index,$cert) {
		return CkJavaKeyStore_TrustedCertAt($this->_cPtr,$index,$cert);
	}

	/**
	 * Searches the trusted-certificate entries for an alias equal to ARG1 and loads the matching certificate into ARG3. ARG2 controls whether the alias comparison is case-sensitive.
	 * @see https://www.chilkatsoft.com/refdoc/phpCkJavaKeyStoreRef.html#TrustedCertOf
	 * @param ?string $alias
	 * @param bool $caseSensitive
	 * @param CkCert $cert
	 * @return bool
	 */
	function TrustedCertOf($alias,$caseSensitive,$cert) {
		return CkJavaKeyStore_TrustedCertOf($this->_cPtr,$alias,$caseSensitive,$cert);
	}

	/**
	 * Adds ARG1 to the certificate sources Chilkat searches when it needs issuer certificates to build a private-key certificate chain. This is useful before calling AddPrivateKey or AddPfx when the supplied certificate material does not already contain the complete chain.Lookup source only: Registering a certificate vault does not copy all vault certificates into the Java keystore and does not create trusted-certificate entries. Certificates are consulted only as candidates for chain construction.
	 * @see https://www.chilkatsoft.com/refdoc/phpCkJavaKeyStoreRef.html#UseCertVault
	 * @param CkXmlCertVault $vault
	 * @return bool
	 */
	function UseCertVault($vault) {
		return CkJavaKeyStore_UseCertVault($this->_cPtr,$vault);
	}
